pub fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // We assume `a.len() == b.len()`. If this is violated, we panic.
    assert_eq!(
        a.len(),
        b.len(),
        "Input vectors must have the same length"
    );

    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| (x as i32) > (y as i32))
     .collect()
}

